  // Fetch foods from backend
  const fetchFoods = async () => {
    try {
      const res = await axios.get("http://localhost:3000/api/food");
      const dbFoods = res.data.map((f) => ({
        ...f,
        _id: f._id || f.id,
        creator: f.createdBy || f.creator || null,
      }));
      setFoods([...defaultFoods, ...dbFoods]);
    } catch (err) {
      console.error("❌ Error fetching foods:", err);
    }
  };

  useEffect(() => {
    fetchFoods();
  }, [user]);

  // Filter foods
  useEffect(() => {
    const parsedBudget = Number(budget);
    const filtered = foods.filter((food) => {
      const nameMatch = food.name
        ?.toLowerCase()
        .includes(searchTerm.toLowerCase());
      const categoryMatch = category === "" || food.category === category;
      const budgetMatch = budget === "" ? true : food.price <= parsedBudget;
      return nameMatch && categoryMatch && budgetMatch;
    });
    setFilteredFoods(filtered);
  }, [foods, searchTerm, category, budget]);

  // Add food (creator only)
  const addFood = async (formData) => {
    const token = localStorage.getItem("token");
    console.log("🔹 token sending from frontend:", token);


    if (!token) {
      alert("❌ You must be logged in as a creator to add food.");
      return;
    }

    try {
      const res = await axios.post(
        "http://localhost:3000/api/food/add",
        formData,
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`, // ✅ Bearer token
          },
        }
      );
      setFoods((prev) => [...prev, res.data]);
      alert("✅ Food added successfully!");
    } catch (err) {
      console.error("Add food error:", err.response?.data || err.message);
      alert(err.response?.data?.message || "Failed to add food.");
    }
  };

  // Delete food
  const deleteFood = async (id) => {
    const token = localStorage.getItem("token");
    if (!token) return alert("❌ Login required");

    try {
      await axios.delete(`http://localhost:3000/api/food/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setFoods((prev) => prev.filter((f) => f._id !== id));
      alert("✅ Food deleted successfully!");
    } catch (err) {
      console.error("❌ Delete error:", err.response?.data || err.message);
      alert(err.response?.data?.message || "Delete failed.");
    }
  };

  // Update food
  const updateFood = async (id, updatedData) => {
    const token = localStorage.getItem("token");
    if (!token) return alert("❌ Login required");

    try {
      const res = await axios.put(
        `http://localhost:3000/api/food/${id}`,
        updatedData,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      const updated = res.data;
      setFoods((prev) =>
        prev.map((f) => (f._id === id ? { ...updated, creator: f.creator } : f))
      );
      alert("✅ Food updated successfully!");
    } catch (err) {
      console.error("❌ Update error:", err.response?.data || err.message);
      alert(err.response?.data?.message || "Update failed.");
    }
  };

  return (
    <FoodContext.Provider
      value={{
        foods,
        filteredFoods,
        searchTerm,
        setSearchTerm,
        budget,
        setBudget,
        category,
        setCategory,
        addFood,
        deleteFood,
        updateFood,
      }}
    >
      {children}
    </FoodContext.Provider>
  );
